        dim3 grid((N + 15) / 16, (M + 15) / 16);
        bf16_gemm_scalar_fallback_kernel<<<grid, block, 0, stream>>>(A, B, C, M, K, N);
        CUDA_CHECK(cudaGetLastError());
        return;
